<?php require 'includes/init.php';require_admin();$db=Database::conn();$one=fn($sql)=>$db->query($sql)->fetchColumn();$recent=$db->query("SELECT bk.booking_ref,bk.total_amount,bk.status,bk.created_at,u.full_name,r.origin,r.destination FROM bookings bk JOIN users u ON u.id=bk.user_id JOIN trips t ON t.id=bk.trip_id JOIN routes r ON r.id=t.route_id ORDER BY bk.created_at DESC LIMIT 10")->fetchAll();include 'includes/header.php'; ?>
<main class="page"><div class="wrap"><div class="welcome"><h2>Admin Dashboard</h2><a class="btn primary" href="admin-passengers.php">Manage Passengers</a></div><div class="stats"><div class="card stat"><span>Total Passengers</span><strong><?= (int)$one("SELECT COUNT(*) FROM users WHERE role='passenger'") ?></strong></div><div class="card stat"><span>Confirmed Bookings</span><strong><?= (int)$one("SELECT COUNT(*) FROM bookings WHERE status='confirmed'") ?></strong></div><div class="card stat"><span>Total Buses</span><strong><?= (int)$one("SELECT COUNT(*) FROM buses") ?></strong></div><div class="card stat"><span>Total Revenue</span><strong><?= naira($one("SELECT COALESCE(SUM(amount),0) FROM payments WHERE status='success'")) ?></strong></div></div><div class="card panel"><h3>Recent Bookings</h3><div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>Passenger</th><th>Route</th><th>Date</th><th>Amount</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $r): ?><tr><td><?= e($r['booking_ref']) ?></td><td><?= e($r['full_name']) ?></td><td><?= e($r['origin'].' → '.$r['destination']) ?></td><td><?= date('d M Y',strtotime($r['created_at'])) ?></td><td><?= naira($r['total_amount']) ?></td><td><span class="status <?= in_array($r['status'],['cancelled','expired'])?'cancel':'' ?>"><?= e(ucfirst($r['status'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div></div></div></main><?php include 'includes/footer.php'; ?>
